use vstd::prelude::*;

verus! {

fn reverse(v: &mut Vec<u64>)
    ensures
        v@ == old(v)@.reverse(),
        v@.len() == old(v)@.len(),
{
    let n: usize = v.len();
    let ghost oldv = old(v)@;

    let mut i: usize = 0;

    while i < n / 2
        invariant
            v@.len() == n,
            n == oldv.len(),

            // Elements already swapped on the left side:
            forall|k: int|
                0 <= k < i as int ==>
                    v@[k] == oldv[(n as int - 1 - k)],

            // Elements already swapped on the right side:
            forall|k: int|
                (n as int - i as int) <= k < n as int ==>
                    v@[k] == oldv[(n as int - 1 - k)],

            // Middle region not yet touched:
            forall|k: int|
                i as int <= k < (n as int - i as int) ==>
                    v@[k] == oldv[k],
        decreases (n / 2) - i,
    {
        let j: usize = n - 1 - i;

        // swap v[i] and v[j] in place
        let tmp = v[i];
        v.set(i, v[j]);
        v.set(j, tmp);

        i = i + 1;
    }

    // At loop exit, all positions are in their reversed place.
    assert(v@ == oldv.reverse());
}

} // verus!

